using System.Collections;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ReplenishAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/Replenish Action")]
public class ReplenishAction : BattleAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private ReshuffleDiscardedDicesHandler reshuffleDiscardedDicesHandler;

	[SerializeField]
	private PlayerDiceInventoryData discard;

	[Header("Debug")]
	[HorizontalLine(2f, EColor.Gray)]
	[SerializeField]
	protected bool verbose;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		return discard.GetDicesAmount() > 0;
	}

	public override void CastAmount(int amount, GameObject source)
	{
		ReferenceSingleton<CoroutineHandler>.Instance.Run(ShuffleCoroutine(amount));
	}

	private IEnumerator ShuffleCoroutine(int amount)
	{
		yield return reshuffleDiscardedDicesHandler.ReshuffleDices();
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.1f, delegate
		{
			ReferenceSingleton<DiceDrawingHandler>.Instance.DrawActionCast(amount);
			$"DRAW ACTION: Drawing {amount.ToString()} dice".DebugLogIfVerbose(verbose);
		});
	}
}
